mapper.select:
SELECT id, user_id, start_at, end_at, include_llm_judge, limit_count,
status, total, processed, report_json, error_message, created_at, updated_at
FROM diet_eval_job
WHERE id = #{id}
AND user_id = #{userId}

mapper.update:
UPDATE diet_eval_job
SET total = #{total}, processed = #{processed}, updated_at = NOW()
WHERE id = #{id}

UPDATE diet_eval_job
SET status = 'DONE', report_json = #{reportJson}, processed = total, updated_at = NOW()
WHERE id = #{id}

UPDATE diet_eval_job
SET status = 'FAILED', error_message = #{errorMessage}, updated_at = NOW()
WHERE id = #{id}
